import{_ as t,o,c as n,a3 as i}from"./chunks/framework.I6s8z2kk.js";const u=JSON.parse('{"title":"Clients","description":"","frontmatter":{},"headers":[],"relativePath":"dev/domain/clients.md","filePath":"dev/domain/clients.md"}'),a={name:"dev/domain/clients.md"};function r(s,e,c,d,l,h){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="clients" tabindex="-1">Clients <a class="header-anchor" href="#clients" aria-label="Permalink to &quot;Clients&quot;">​</a></h1><p>The <strong>Clients</strong> module owns client accounts and their relationship to centers.</p><h2 id="sign-in-and-registration" tabindex="-1">Sign-in and registration <a class="header-anchor" href="#sign-in-and-registration" aria-label="Permalink to &quot;Sign-in and registration&quot;">​</a></h2><p>Clients are created <strong>only by OTP verify</strong>: <code>POST clients/auth/login</code> sends a code, <code>POST clients/auth/verify</code> checks it. Create the account through <code>ClientAuthService::findOrCreateByPhone</code> after a successful verify, which fires <code>ClientRegistered</code>. See <a href="./support">Support</a> for OTP rules.</p><p>A client <strong>needs onboarding</strong> while <code>first_name</code> or <code>last_name</code> is null. <code>PUT clients/profile</code> completes the profile; <code>GET clients/me</code> returns the current client.</p><p><code>POST clients/launch</code> must be called on every app start (30 per minute). It registers or refreshes the device with its FCM token, platform and locale. Without a token the device is stored unlinked and linked on verify when the same <code>device_identifier</code> is sent.</p><p><code>GET clients/bookings</code> is one feed of reservations, packages and memberships, newest first.</p><h2 id="relationship-to-centers" tabindex="-1">Relationship to centers <a class="header-anchor" href="#relationship-to-centers" aria-label="Permalink to &quot;Relationship to centers&quot;">​</a></h2><ul><li>A center sees only clients in <code>center_client</code>, or with a Confirmed or Completed purchase where it is the merchant. Never list clients across centers.</li><li>A center can <strong>block</strong> a client (<code>blocked-clients</code>). Blocked clients cannot book that center.</li><li>Clients are <strong>soft-deleted</strong>; raw queries must filter <code>deleted_at</code>.</li></ul><h2 id="favorites-and-ratings" tabindex="-1">Favorites and ratings <a class="header-anchor" href="#favorites-and-ratings" aria-label="Permalink to &quot;Favorites and ratings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET/POST clients/favorites</code>, <code>DELETE clients/favorites/{center}</code></td><td>Favorite centers</td></tr><tr><td><code>POST clients/ratings</code></td><td>Rate a center. Aggregates feed center lists and <code>top_centers</code>.</td></tr></tbody></table><h2 id="admin" tabindex="-1">Admin <a class="header-anchor" href="#admin" aria-label="Permalink to &quot;Admin&quot;">​</a></h2><p><code>admin/clients</code> (list, show, search, export) with <code>clients.view_any</code>, <code>clients.view</code> and <code>clients.export</code>.</p><p>The list and export take <code>sort</code> (<code>AdminClientQuery::SORTS</code>): <code>name</code> (first, then last name), <code>created_at</code>, <code>centers_count</code> or <code>reservations_count</code>, <code>-</code> for descending; newest first without it. See <a href="./../conventions/coding#list-sorting">List sorting</a>.</p><p><code>POST admin/clients/{client}/otp</code> with <code>otps.create</code> issues a login code for the client and returns it once, without an SMS. See <a href="./support#admin-issued-codes">Support: OTP</a>.</p>',15)])])}const f=t(a,[["render",r]]);export{u as __pageData,f as default};
